212	    {
213	        std::map<size_t, Strings> replica_adresses;
214	
215	        for (const auto & [_, node] : cluster_info.nodes_info)
216	        {
217	            if (cluster_info.current_node.secure != node.secure)
218	            {
219	                LOG_WARNING(log, "Node '{}' in cluster '{}' has different 'secure' value, skipping it", node.address, cluster_info.name);
220	                continue;
221	            }
222	            replica_adresses[node.shard_id].emplace_back(node.address);
223	        }
224	
225	        shards.reserve(replica_adresses.size());
226	        for (auto & [_, replicas] : replica_adresses)
227	            shards.emplace_back(std::move(replicas));
228	    }
229	
230	    bool secure = cluster_info.current_node.secure;
